-- BharatMart Supply Chain Analytics - Small MySQL Version
-- Generated from BharatMart_Supply_Chain_Cleaned(2).xlsx
-- Small relational dataset for MySQL Workbench and SQL interview practice

DROP DATABASE IF EXISTS bharatmart_supply_chain;
CREATE DATABASE bharatmart_supply_chain;
USE bharatmart_supply_chain;

CREATE TABLE `Customers` (
  `Customer_ID` VARCHAR(50) NOT NULL,
  `Customer_Name` VARCHAR(50),
  `Customer_Type` VARCHAR(50),
  `Industry` VARCHAR(50),
  `City` VARCHAR(50),
  `State` VARCHAR(50),
  `Country` VARCHAR(50),
  `Region` VARCHAR(50),
  `City_Tier` VARCHAR(50),
  `Segment` VARCHAR(50),
  `Customer_Tier` VARCHAR(50),
  `Account_Manager` VARCHAR(50),
  `Registration_Date` DATETIME,
  `Credit_Rating` VARCHAR(50),
  `Payment_Terms` VARCHAR(50),
  `SLA_Level` VARCHAR(50),
  `Customer_Status` VARCHAR(50),
  PRIMARY KEY (`Customer_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Products` (
  `Product_ID` VARCHAR(50) NOT NULL,
  `Product_Name` VARCHAR(50),
  `SKU` VARCHAR(50),
  `Category` VARCHAR(50),
  `Sub_Category` VARCHAR(50),
  `Brand` VARCHAR(50),
  `Unit` VARCHAR(50),
  `Unit_Cost` DECIMAL(18,2),
  `Selling_Price` DECIMAL(18,2),
  `Weight_KG` DECIMAL(18,2),
  `Volume_M3` DECIMAL(18,2),
  `Shelf_Life_Days` INT,
  `Temperature_Controlled` VARCHAR(50),
  `ABC_Class` VARCHAR(50),
  `Reorder_Level` INT,
  `Safety_Stock` INT,
  `Standard_Lead_Time_Days` INT,
  `Product_Status` VARCHAR(50),
  PRIMARY KEY (`Product_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Suppliers` (
  `Supplier_ID` VARCHAR(50) NOT NULL,
  `Supplier_Name` VARCHAR(50),
  `Supplier_Type` VARCHAR(50),
  `City` VARCHAR(50),
  `State` VARCHAR(50),
  `Country` VARCHAR(50),
  `Region` VARCHAR(50),
  `Category` VARCHAR(50),
  `Supplier_Rating` DECIMAL(18,2),
  `Quality_Rating` INT,
  `Reliability_Rating` INT,
  `Standard_Lead_Time_Days` INT,
  `Payment_Terms` VARCHAR(50),
  `Minimum_Order_Qty` INT,
  `Contract_Start` DATETIME,
  `Contract_End` DATETIME,
  `Supplier_Status` VARCHAR(50),
  PRIMARY KEY (`Supplier_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Warehouses` (
  `Warehouse_ID` VARCHAR(50) NOT NULL,
  `Warehouse_Name` VARCHAR(50),
  `City` VARCHAR(50),
  `State` VARCHAR(50),
  `Region` VARCHAR(50),
  `Warehouse_Type` VARCHAR(50),
  `Capacity_Units` INT,
  `Current_Utilization_Percentage` DECIMAL(18,2),
  `Manager` VARCHAR(50),
  `Operating_Hours` VARCHAR(50),
  `Loading_Docks` INT,
  `Storage_Type` VARCHAR(50),
  `Temperature_Controlled` VARCHAR(50),
  `Opening_Date` DATETIME,
  `Warehouse_Status` VARCHAR(50),
  PRIMARY KEY (`Warehouse_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Carriers` (
  `Carrier_ID` VARCHAR(50) NOT NULL,
  `Carrier_Name` VARCHAR(50),
  `Carrier_Type` VARCHAR(50),
  `Service_Type` VARCHAR(50),
  `Region` VARCHAR(50),
  `Average_Transit_Days` DECIMAL(18,2),
  `Contract_Rate_Per_KM` DECIMAL(18,2),
  `On_Time_Target` DECIMAL(18,2),
  `Damage_Target` DECIMAL(18,2),
  `Capacity_Units` INT,
  `Carrier_Rating` DECIMAL(18,2),
  `Contract_Start` DATETIME,
  `Contract_End` DATETIME,
  `Carrier_Status` VARCHAR(50),
  PRIMARY KEY (`Carrier_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Calendar` (
  `Date` DATE NOT NULL,
  `Day` INT,
  `Day_Name` VARCHAR(50),
  `Month` INT,
  `Month_Name` VARCHAR(50),
  `Quarter` VARCHAR(50),
  `Year` INT,
  `Financial_Year` VARCHAR(50),
  `Is_Weekend` VARCHAR(50),
  `Is_Holiday` VARCHAR(50),
  `Holiday_Name` VARCHAR(50),
  PRIMARY KEY (`Date`)
) ENGINE=InnoDB;

CREATE TABLE `Orders` (
  `Order_ID` VARCHAR(50) NOT NULL,
  `Customer_ID` VARCHAR(50),
  `Order_Date` DATETIME,
  `Required_Date` DATETIME,
  `Promised_Date` DATETIME,
  `Priority` VARCHAR(50),
  `Order_Status` VARCHAR(50),
  `Warehouse_ID` VARCHAR(50),
  `Sales_Channel` VARCHAR(50),
  `Shipping_City` VARCHAR(50),
  `Shipping_State` VARCHAR(50),
  `Region` VARCHAR(50),
  `Payment_Status` VARCHAR(50),
  `Payment_Terms` VARCHAR(50),
  `Total_Order_Value` DECIMAL(18,2),
  `Column1` INT,
  PRIMARY KEY (`Order_ID`),
  FOREIGN KEY (`Customer_ID`) REFERENCES `Customers`(`Customer_ID`),
  FOREIGN KEY (`Warehouse_ID`) REFERENCES `Warehouses`(`Warehouse_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Order_Items` (
  `Order_Item_ID` VARCHAR(50) NOT NULL,
  `Order_ID` VARCHAR(50),
  `Product_ID` VARCHAR(50),
  `Quantity_Ordered` INT,
  `Unit_Price` DECIMAL(18,2),
  `Discount_Percentage` DECIMAL(18,2),
  `Gross_Value` DECIMAL(18,2),
  `Discount_Amount` DECIMAL(18,2),
  `Net_Value` DECIMAL(18,2),
  `Requested_Date` DATETIME,
  `Allocated_Quantity` INT,
  `Backordered_Quantity` INT,
  `Fulfillment_Status` VARCHAR(50),
  PRIMARY KEY (`Order_Item_ID`),
  FOREIGN KEY (`Order_ID`) REFERENCES `Orders`(`Order_ID`),
  FOREIGN KEY (`Product_ID`) REFERENCES `Products`(`Product_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Purchase_Orders` (
  `PO_ID` VARCHAR(50) NOT NULL,
  `Supplier_ID` VARCHAR(50),
  `Product_ID` VARCHAR(50),
  `Warehouse_ID` VARCHAR(50),
  `PO_Date` DATETIME,
  `Expected_Date` DATETIME,
  `Actual_Receipt_Date` DATETIME,
  `Quantity_Ordered` INT,
  `Quantity_Received` INT,
  `Unit_Cost` DECIMAL(18,2),
  `PO_Value` DECIMAL(18,2),
  `PO_Status` VARCHAR(50),
  `Quality_Status` VARCHAR(50),
  `Rejected_Quantity` INT,
  `Delay_Days` INT,
  `ON_Flag` INT,
  PRIMARY KEY (`PO_ID`),
  FOREIGN KEY (`Supplier_ID`) REFERENCES `Suppliers`(`Supplier_ID`),
  FOREIGN KEY (`Product_ID`) REFERENCES `Products`(`Product_ID`),
  FOREIGN KEY (`Warehouse_ID`) REFERENCES `Warehouses`(`Warehouse_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Inventory` (
  `Inventory_ID` VARCHAR(50) NOT NULL,
  `Warehouse_ID` VARCHAR(50),
  `Product_ID` VARCHAR(50),
  `Snapshot_Date` DATETIME,
  `Opening_Stock` INT,
  `Received_Quantity` INT,
  `Issued_Quantity` INT,
  `Closing_Stock` INT,
  `Reserved_Stock` INT,
  `Available_Stock` INT,
  `Damaged_Stock` INT,
  `Expired_Stock` INT,
  `Stockout_Flag` VARCHAR(50),
  `Days_of_Inventory` DECIMAL(18,2),
  `Inventory_Value` DECIMAL(18,2),
  PRIMARY KEY (`Inventory_ID`),
  FOREIGN KEY (`Warehouse_ID`) REFERENCES `Warehouses`(`Warehouse_ID`),
  FOREIGN KEY (`Product_ID`) REFERENCES `Products`(`Product_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Shipments` (
  `Shipment_ID` VARCHAR(50) NOT NULL,
  `Order_ID` VARCHAR(50),
  `Warehouse_ID` VARCHAR(50),
  `Carrier_ID` VARCHAR(50),
  `Shipment_Date` DATETIME,
  `Promised_Date` DATETIME,
  `Actual_Delivery_Date` DATETIME,
  `Quantity_Ordered` INT,
  `Quantity_Shipped` INT,
  `Quantity_Delivered` INT,
  `Shipping_Mode` VARCHAR(50),
  `Distance_KM` INT,
  `Transporting_Cost` DECIMAL(18,2),
  `Fuel_Surcharge` DECIMAL(18,2),
  `Damage_Quantity` INT,
  `Delivery_Status` VARCHAR(50),
  `Delay_Days` INT,
  `On_Time_Flag` INT,
  `In_Full_Flag` INT,
  `OTIF_Flag` INT,
  PRIMARY KEY (`Shipment_ID`),
  FOREIGN KEY (`Order_ID`) REFERENCES `Orders`(`Order_ID`),
  FOREIGN KEY (`Warehouse_ID`) REFERENCES `Warehouses`(`Warehouse_ID`),
  FOREIGN KEY (`Carrier_ID`) REFERENCES `Carriers`(`Carrier_ID`)
) ENGINE=InnoDB;

CREATE TABLE `Delivery_Events` (
  `Event_ID` VARCHAR(50) NOT NULL,
  `Shipment_ID` VARCHAR(50),
  `Event_DateTime` DATETIME,
  `Event_Type` VARCHAR(50),
  `Location` VARCHAR(50),
  `Facility_ID` VARCHAR(50),
  `Status` VARCHAR(50),
  `Delay_Hours` INT,
  PRIMARY KEY (`Event_ID`),
  FOREIGN KEY (`Shipment_ID`) REFERENCES `Shipments`(`Shipment_ID`)
) ENGINE=InnoDB;

